insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'1-nombres-relatifs','Les nombres relatifs','Un nombre relatif possède un signe : positif ou négatif. Ajouter un nombre positif fait avancer vers la droite ; ajouter un nombre négatif fait reculer vers la gauche.
Pour additionner deux nombres de signes opposés, compare leurs distances à zéro. Le résultat prend le signe du nombre le plus éloigné de zéro.','Tu es au sous-sol −4. Tu montes de 7 étages : tu arrives au 3e. Le signe indique une direction, pas une erreur !','Additionner les distances sans tenir compte des signes ne donne pas le bon étage.','integers',1,true,'{"description":"Avancer et reculer sur la droite des nombres.","method":["Repère le point de départ.","Lis le signe du déplacement.","Déplace-toi puis vérifie le signe du résultat."],"example":"−4 + 7 = 3 : pars de −4 et avance de 7 unités.","analogyTitle":"L’ascenseur","emoji":"🛗","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='1-nombres'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'1-priorites','Les priorités opératoires','Les parenthèses passent d’abord, puis les puissances, puis les multiplications et divisions, enfin les additions et soustractions.
À priorité égale, calcule de gauche à droite. Une multiplication ne passe pas automatiquement avant une division.','Tu prépares d’abord les petits mélanges indiqués par les parenthèses, puis tu assembles le plat. Changer l’ordre peut changer le résultat.','Calculer tout de gauche à droite sans respecter les priorités.','order_operations',2,true,'{"description":"Choisir la bonne opération au bon moment.","method":["Repère les parenthèses et les puissances.","Effectue les multiplications et divisions.","Termine par les additions et soustractions."],"example":"3 + 4 × 5 = 3 + 20 = 23, alors que (3 + 4) × 5 = 35.","analogyTitle":"La recette de cuisine","emoji":"🥣","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='1-nombres'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'1-fractions-equivalentes','Les fractions équivalentes','Une fraction représente un quotient. Multiplier son numérateur et son dénominateur par le même nombre non nul conserve sa valeur.
On peut aussi les diviser par un diviseur commun non nul pour simplifier la fraction.','Deux grandes portions sur trois représentent la même quantité que huit petites portions sur douze. Tu redécoupes le chocolat, tu n’en ajoutes pas.','Multiplier uniquement le dénominateur change la quantité représentée.','equivalent_fractions',3,true,'{"description":"La même quantité, avec d’autres parts.","method":["Compare les deux dénominateurs.","Trouve le facteur multiplicatif.","Applique le même facteur au numérateur."],"example":"2/3 = 8/12, car 3 × 4 = 12 et 2 × 4 = 8.","analogyTitle":"La tablette de chocolat","emoji":"🍫","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='1-nombres'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'1-pourcentages','Comprendre les pourcentages','p % signifie p sur 100. Pour calculer p % d’une quantité Q, calcule Q × p / 100.
Distingue la part et le total : une réduction de 20 % n’est pas le prix à payer, mais le montant retiré.','Imagine une grille de 100 cases : 15 % en colore 15. Si la grille représente 80 euros, ces cases valent ensemble 12 euros.','Confondre le montant de la réduction et le prix restant.','percentage',4,true,'{"description":"Une proportion sur cent.","method":["Identifie la quantité totale.","Multiplie-la par le pourcentage.","Divise par 100."],"example":"15 % de 80 = 80 × 15 / 100 = 12.","analogyTitle":"Cent petites cases","emoji":"🟨","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='1-nombres'
