insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'1-perimetre','Le périmètre du rectangle','Le périmètre est la longueur du contour. Un rectangle possède deux longueurs L et deux largeurs l : P = 2 × (L + l).
Exprime toutes les dimensions dans la même unité avant de calculer. Le périmètre s’exprime en unités de longueur.','Pour clôturer un jardin, tu mesures chacun de ses quatre côtés. La surface de gazon n’indique pas la longueur de clôture nécessaire.','Utiliser L × l donne une aire, pas un périmètre.','perimeter',5,true,'{"description":"Mesurer le tour d’une figure.","method":["Additionne une longueur et une largeur.","Multiplie la somme par 2.","Indique l’unité de longueur."],"example":"Pour L = 8 m et l = 3 m : P = 2 × (8 + 3) = 22 m.","analogyTitle":"La clôture du jardin","emoji":"🏡","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='1-geometrie'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'1-angles-triangle','Les angles d’un triangle','Dans le plan, la somme des trois angles intérieurs d’un triangle vaut 180°. Si deux angles sont connus, le troisième est 180° moins leur somme.
Un triangle rectangle possède un angle de 90° ; ses deux autres angles se complètent donc à 90°.','Les trois angles se partagent toujours le même budget. Ce que deux angles utilisent n’est plus disponible pour le troisième.','Soustraire de 360° au lieu de 180° : ici, on parle d’un triangle.','triangle_angles',6,true,'{"description":"Retrouver l’angle manquant.","method":["Additionne les deux angles connus.","Soustrais leur somme de 180°.","Vérifie que les trois angles totalisent 180°."],"example":"Avec 50° et 65°, le dernier angle vaut 180 − 50 − 65 = 65°.","analogyTitle":"Un budget de 180 degrés","emoji":"📐","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='1-geometrie'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'fractions-meme-denominateur','Additionner des fractions','Pour additionner des fractions de même dénominateur, additionne les numérateurs et garde le dénominateur.
Si les dénominateurs sont différents, commence par écrire des fractions équivalentes de même dénominateur. Simplifie ensuite si possible.','Deux parts plus trois parts d’une pizza coupée en sept donnent cinq parts sur sept. La taille de chaque part ne change pas !','On n’additionne pas les dénominateurs : ils indiquent la taille des parts.','fractions',1,true,'{"description":"Réunir des parts de même taille.","method":["Vérifie que les dénominateurs sont identiques.","Additionne seulement les numérateurs.","Conserve le dénominateur puis simplifie."],"example":"2/7 + 3/7 = 5/7.","analogyTitle":"Une histoire de pizza","emoji":"🍕","minutes":8,"track":"general","content_version":2}'::jsonb
