insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'equation-additive','Les premières équations','Résoudre une équation consiste à trouver les valeurs qui rendent l’égalité vraie. Dans x + a = b, on soustrait a aux deux membres pour obtenir x = b − a.
Une même addition ou soustraction des deux côtés conserve les solutions.','Si tu retires un poids d’un plateau, tu retires le même de l’autre. La balance reste en équilibre et l’inconnue finit par se retrouver seule.','Ajouter au lieu de soustraire, ou modifier un seul membre de l’égalité.','equations',2,true,'{"description":"Trouver l’inconnue en gardant l’équilibre.","method":["Repère ce qui accompagne x.","Effectue l’opération inverse des deux côtés.","Remplace x par ta réponse pour vérifier."],"example":"x + 6 = 14 donne x = 14 − 6 = 8.","analogyTitle":"La balance à plateaux","emoji":"⚖️","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='2-algebre'
