insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'aire-rectangle','Les aires du rectangle','L’aire d’un rectangle vaut A = L × l. Les longueurs doivent être exprimées dans la même unité.
Une aire compte des unités carrées : des côtés en mètres donnent une aire en m². Pour convertir des aires, le facteur de conversion des longueurs est mis au carré.','Six rangées de quatre carreaux de 1 m² recouvrent 24 m². On compte les carreaux à l’intérieur, pas ceux qui longent le bord.','Ne confonds pas l’aire L × l et le périmètre 2 × (L + l).','geometry',3,true,'{"description":"Mesurer une surface avec des unités carrées.","method":["Exprime les dimensions dans la même unité.","Multiplie longueur et largeur.","Exprime la surface dans l’unité carrée."],"example":"Un rectangle de 6 m sur 4 m a une aire de 24 m².","analogyTitle":"Les carreaux du sol","emoji":"🟩","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='2-geometrie'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'2-puissances','Multiplier des puissances','Pour une même base a, aᵐ × aⁿ = aᵐ⁺ⁿ : tu réunis les facteurs identiques.
En revanche, (aᵐ)ⁿ = aᵐⁿ. Ces règles ne s’appliquent pas à une addition de puissances.','Une boîte contient trois facteurs 2, l’autre en contient quatre. En réunissant les boîtes, tu as sept facteurs 2 à multiplier.','Multiplier les exposants dans un produit de puissances au lieu de les additionner.','powers',4,true,'{"description":"Même base, exposants qui s’additionnent.","method":["Vérifie que les bases sont les mêmes.","Repère s’il s’agit d’un produit.","Additionne les exposants et conserve la base."],"example":"2³ × 2⁴ = 2⁷ : il y a 7 facteurs égaux à 2.","analogyTitle":"Les boîtes de facteurs","emoji":"📦","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='2-nombres'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'2-proportionnalite','La proportionnalité','Deux grandeurs sont proportionnelles si on passe de l’une à l’autre par un même facteur. Dans un tableau proportionnel, le quotient de deux valeurs correspondantes est constant.
Le passage par l’unité permet de retrouver n’importe quelle valeur.','Si trois portions demandent neuf cuillères, chaque portion en demande trois. Pour cinq portions, tu en prépares quinze.','Ajouter la même différence aux deux grandeurs ne conserve pas toujours la proportion.','proportion',5,true,'{"description":"Passer par une unité pour changer d’échelle.","method":["Calcule la valeur pour une unité.","Multiplie par le nombre d’unités demandé.","Vérifie que le prix unitaire est conservé."],"example":"3 cahiers coûtent 9 € : 1 coûte 3 €, donc 5 coûtent 15 €.","analogyTitle":"La recette pour plus d’amis","emoji":"🥞","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='2-algebre'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'2-moyenne','La moyenne arithmétique','La moyenne d’une série vaut la somme des valeurs divisée par leur nombre. Chaque valeur compte, y compris les répétitions.
La moyenne peut être différente de toutes les valeurs observées et elle est sensible aux valeurs extrêmes.','On met toutes les billes de trois amis dans un sac, puis on les partage également. La part de chacun est la moyenne.','Diviser par la plus grande valeur au lieu de diviser par l’effectif.','mean',6,true,'{"description":"Répartir un total équitablement.","method":["Additionne toutes les valeurs.","Compte combien de valeurs sont présentes.","Divise la somme par ce nombre."],"example":"Pour 8, 12 et 16, la moyenne vaut 36 / 3 = 12.","analogyTitle":"Le partage des billes","emoji":"🔵","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='2-statistiques'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'3-equations','Équations du premier degré','Pour résoudre ax + b = c avec a non nul, commence par retirer b, puis divise par a : x = (c − b) / a.
Tu peux additionner ou soustraire la même quantité aux deux membres, puis les multiplier ou diviser par un même nombre non nul.','Trois sacs et quatre billes font dix-neuf billes. Enlève les quatre billes isolées, puis partage les quinze restantes entre les trois sacs.','Diviser seulement un terme du membre droit au lieu de toute la différence.','linear_equation',1,true,'{"description":"Isoler x en deux opérations.","method":["Soustrais le terme constant des deux côtés.","Divise les deux membres par le coefficient de x.","Vérifie dans l’équation de départ."],"example":"3x + 4 = 19 → 3x = 15 → x = 5.","analogyTitle":"Les sacs identiques","emoji":"🎒","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='3-algebre'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'3-distributivite','Développer et réduire','La distributivité donne a(bx + c) = abx + ac. Le facteur devant la parenthèse multiplie chacun des termes à l’intérieur.
On réduit ensuite les termes de même nature. Un terme en x ne s’additionne pas directement à une constante.','Le facteur distribue un cadeau à tous les termes dans la parenthèse. Aucun terme ne doit être oublié.','Distribuer le facteur au premier terme seulement, ou additionner un terme en x et un nombre.','distributivity',2,true,'{"description":"Distribuer un facteur à chaque terme.","method":["Multiplie le facteur par le terme en x.","Multiplie-le aussi par la constante.","Regroupe seulement les termes semblables."],"example":"3(2x + 4) + 5x = 6x + 12 + 5x = 11x + 12.","analogyTitle":"Un cadeau pour chaque personne","emoji":"🎁","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='3-algebre'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'3-pythagore','Le théorème de Pythagore','Dans un triangle rectangle, le carré de l’hypoténuse est la somme des carrés des deux autres côtés : c² = a² + b².
L’hypoténuse est opposée à l’angle droit et constitue le côté le plus long. Pour trouver c, prends la racine carrée de la somme.','Traverser un terrain en diagonale est plus court que longer deux côtés. Pythagore retrouve la longueur exacte de ce raccourci.','a + b n’est pas l’hypoténuse : la relation porte sur les carrés.','pythagoras',3,true,'{"description":"Relier les côtés d’un triangle rectangle.","method":["Vérifie que le triangle est rectangle.","Identifie l’hypoténuse.","Additionne les carrés des deux autres côtés puis prends la racine."],"example":"Avec 6 cm et 8 cm : c² = 36 + 64 = 100, donc c = 10 cm.","analogyTitle":"Le raccourci en diagonale","emoji":"🪜","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='3-geometrie'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'3-fonction-affine','Lire une fonction affine','Une fonction affine s’écrit f(x) = ax + b. Le coefficient a est le taux de variation ; b est la valeur de f(0).
Pour calculer une image, remplace chaque x par le nombre demandé en respectant les priorités opératoires.','Un taxi peut demander un montant de départ puis un prix fixe par kilomètre. Le montant de départ joue le rôle de b, le prix par kilomètre celui de a.','Confondre l’image f(x) et le nombre de départ x.','affine',4,true,'{"description":"Une valeur de départ et un rythme constant.","method":["Identifie le nombre dont tu cherches l’image.","Remplace x dans la formule.","Multiplie puis additionne."],"example":"Si f(x) = 3x + 2, alors f(4) = 3 × 4 + 2 = 14.","analogyTitle":"Le prix d’un trajet","emoji":"🚕","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='3-fonctions'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'3-pente','Le coefficient directeur','Pour deux points A(x₁ ; y₁) et B(x₂ ; y₂) avec x₁ ≠ x₂, la pente vaut (y₂ − y₁) / (x₂ − x₁).
Une pente positive décrit une droite montante quand on va vers la droite ; une pente négative décrit une droite descendante.','La pente compare la hauteur gagnée à la distance horizontale parcourue. Monter de deux mètres pour un mètre horizontal donne une pente de 2.','Inverser la variation verticale et la variation horizontale.','slope',5,true,'{"description":"Mesurer la variation d’une droite.","method":["Calcule la variation verticale y₂ − y₁.","Calcule la variation horizontale x₂ − x₁.","Divise en gardant le même ordre pour les deux différences."],"example":"A(1 ; 3), B(4 ; 9) : a = (9 − 3) / (4 − 1) = 2.","analogyTitle":"La rampe","emoji":"⛰️","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='3-fonctions'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'3-frequences','Effectifs et fréquences','L’effectif compte les observations d’une catégorie. Sa fréquence vaut effectif de la catégorie / effectif total.
Une fréquence est comprise entre 0 et 1. Pour l’exprimer en pourcentage, multiplie-la par 100.','Une fréquence permet de comparer des classes de tailles différentes : dix élèves n’ont pas le même poids dans une classe de vingt et dans une classe de trente.','Diviser par l’effectif des autres catégories au lieu du total.','frequency',6,true,'{"description":"Passer d’un nombre à une proportion.","method":["Repère l’effectif de la catégorie.","Repère l’effectif total.","Divise puis multiplie par 100 si un pourcentage est demandé."],"example":"8 élèves sur 20 représentent 8 / 20 = 0,4 = 40 %.","analogyTitle":"Le sondage de la classe","emoji":"📊","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='3-statistiques'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'4-second-degre','Les racines d’un trinôme','Un produit vaut zéro si au moins un de ses facteurs vaut zéro. Pour (x − r)(x − s) = 0, les solutions sont x = r ou x = s.
Cette propriété concerne un produit égal à zéro. Développer n’est pas toujours nécessaire pour résoudre.','Dans une chaîne, il suffit qu’un facteur soit nul pour que tout le produit s’annule. Chaque facteur offre une possibilité.','Changer le signe de la racine : x − 5 = 0 donne x = 5, pas −5.','quadratic_roots',1,true,'{"description":"Utiliser une forme factorisée.","method":["Vérifie que le produit est égal à zéro.","Annule séparément chaque facteur.","Énonce les deux solutions, puis sélectionne celle demandée."],"example":"(x − 2)(x − 5) = 0 a pour solutions 2 et 5 ; la plus grande est 5.","analogyTitle":"Les deux interrupteurs","emoji":"🔌","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='4-algebre'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'4-systemes','Résoudre un système','Une solution d’un système satisfait toutes ses équations à la fois. On peut additionner les équations pour éliminer une inconnue.
Avec x + y = S et x − y = D, l’addition donne 2x = S + D. Puis y = S − x.','Connaître la somme de deux âges ne suffit pas. Avec leur différence, tu possèdes un second indice qui permet de retrouver les deux âges.','Une paire qui vérifie une seule équation n’est pas une solution du système.','system',2,true,'{"description":"Deux informations pour deux inconnues.","method":["Cherche des coefficients opposés.","Additionne les équations pour éliminer une inconnue.","Trouve l’autre inconnue et vérifie les deux équations."],"example":"x + y = 12 et x − y = 4 → 2x = 16 → x = 8 et y = 4.","analogyTitle":"Deux indices","emoji":"🕵️","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='4-algebre'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'4-trigonometrie','Le sinus dans un triangle','Dans un triangle rectangle, le sinus d’un angle aigu est le côté opposé à cet angle divisé par l’hypoténuse.
Les noms « opposé » et « adjacent » dépendent de l’angle choisi. L’hypoténuse reste le côté opposé à l’angle droit.','Pour un même angle, une petite échelle et une grande gardent le même rapport hauteur / longueur. Ce rapport est le sinus de l’angle au sol.','Inverser le rapport : pour un angle aigu, le sinus est toujours compris entre 0 et 1.','sine_ratio',3,true,'{"description":"Un rapport de longueurs lié à un angle.","method":["Identifie l’angle étudié.","Repère le côté opposé et l’hypoténuse.","Calcule le rapport opposé / hypoténuse."],"example":"Si le côté opposé mesure 6 et l’hypoténuse 10 : sin(α) = 6/10 = 0,6.","analogyTitle":"Une échelle contre un mur","emoji":"🪜","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='4-trigonometrie'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'4-similitude','Les figures semblables','Des figures semblables ont les mêmes angles et des côtés correspondants proportionnels. Si le rapport d’agrandissement vaut k, chaque longueur est multipliée par k.
Les aires, elles, sont multipliées par k². Il faut donc identifier la grandeur demandée.','Un zoom agrandit toutes les longueurs dans la même proportion. Changer seulement la largeur déformerait l’image.','Appliquer le facteur d’aire k² à une longueur, ou comparer des côtés non correspondants.','similarity',4,true,'{"description":"Agrandir sans déformer.","method":["Associe les côtés correspondants.","Trouve le rapport nouveau / ancien.","Multiplie la longueur cherchée par ce rapport."],"example":"Un côté de 4 cm devient 12 cm : k = 3. Un côté correspondant de 5 cm devient 15 cm.","analogyTitle":"Le zoom d’une photo","emoji":"🔍","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='4-geometrie'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'4-sommet-parabole','Le sommet d’une parabole','Pour f(x) = ax² + bx + c avec a ≠ 0, l’abscisse du sommet vaut −b / (2a). Son ordonnée s’obtient en calculant f à cette abscisse.
Si a > 0, le sommet est un minimum ; si a < 0, c’est un maximum.','La parabole ressemble à un bol lorsque a est positif. Le sommet indique l’endroit le plus bas, pas le point où le bol traverse l’axe horizontal.','Confondre l’abscisse du sommet et une racine de la fonction.','vertex',5,true,'{"description":"Trouver le point où la courbe change de sens.","method":["Identifie a et b avec leurs signes.","Calcule −b / (2a).","Si demandé, remplace x par cette valeur pour trouver l’ordonnée."],"example":"Pour f(x) = 2x² − 12x + 5 : xₛ = 12 / 4 = 3.","analogyTitle":"Le fond du bol","emoji":"🥣","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='4-fonctions'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'4-probabilites','Les probabilités simples','Lorsque les issues élémentaires sont équiprobables, P(A) = nombre d’issues favorables / nombre total d’issues.
Une probabilité est comprise entre 0 et 1. La formule de comptage suppose bien que toutes les issues ont la même chance.','Si les billes sont identiques au toucher et bien mélangées, chaque bille a la même chance de sortir. La couleur regroupe plusieurs issues favorables.','Diviser par le nombre d’issues défavorables plutôt que par le total.','probability',6,true,'{"description":"Compter les issues favorables.","method":["Vérifie l’équiprobabilité.","Compte les issues favorables.","Divise par le nombre total d’issues."],"example":"Un sac contient 3 billes rouges et 5 bleues : P(rouge) = 3/8.","analogyTitle":"La pioche à l’aveugle","emoji":"🎲","minutes":8,"track":"general","content_version":2}'::jsonb
from public.chapters where slug='4-statistiques'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'5-suite-arithmetique','Les suites arithmétiques','Dans une suite arithmétique, on ajoute toujours la même raison r : uₙ₊₁ = uₙ + r. Avec un premier terme u₀, on a uₙ = u₀ + nr.
Si le premier terme s’appelle u₁, la formule devient uₙ = u₁ + (n − 1)r. Lis bien l’indice de départ.','Chaque marche ajoute la même hauteur. Pour connaître ta hauteur après quatre marches, tu ajoutes quatre fois la hauteur d’une marche à celle du départ.','Confondre le nombre de termes et le nombre de passages entre eux.','arithmetic_sequence',1,true,'{"description":"Ajouter la même quantité à chaque étape.","method":["Identifie le premier terme et son indice.","Compte les passages jusqu’au terme demandé.","Multiplie ce nombre de passages par la raison puis ajoute le premier terme."],"example":"u₀ = 5 et r = 3 : u₄ = 5 + 4 × 3 = 17.","analogyTitle":"L’escalier régulier","emoji":"🪜","minutes":10,"track":"general-math6","content_version":2}'::jsonb
from public.chapters where slug='5-suites'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'5-suite-geometrique','Les suites géométriques','Dans une suite géométrique, on multiplie toujours par la même raison q : uₙ₊₁ = q × uₙ. Avec un premier terme u₀, on a uₙ = u₀ × qⁿ.
Une hausse de p % correspond au facteur 1 + p/100 ; une baisse de p % au facteur 1 − p/100.','Chaque personne invite deux nouvelles personnes à l’étape suivante. Le nombre est multiplié, et non augmenté d’une quantité fixe.','Utiliser u₀ + nq : cela décrirait une croissance additive, pas multiplicative.','geometric_sequence',2,true,'{"description":"Multiplier par le même facteur.","method":["Identifie le terme initial et la raison.","Compte les multiplications nécessaires.","Utilise la puissance correspondante."],"example":"u₀ = 3 et q = 2 : u₄ = 3 × 2⁴ = 48.","analogyTitle":"La chaîne des doubles","emoji":"🌱","minutes":10,"track":"general-math6","content_version":2}'::jsonb
from public.chapters where slug='5-suites'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'5-radians','Des degrés aux radians','Un tour complet vaut 360° ou 2π radians. Ainsi, 180° = π radians. Pour convertir d degrés, calcule d × π / 180.
Un angle en radians compare une longueur d’arc au rayon du cercle.','Sur un cercle de rayon 1, un arc de longueur 1 délimite un angle de 1 radian. Le tour complet mesure 2π.','Oublier π, ou convertir dans le mauvais sens.','radians',3,true,'{"description":"Mesurer un angle avec le cercle.","method":["Écris degrés × π / 180.","Simplifie le coefficient devant π.","Vérifie avec les repères π/2 et π."],"example":"120° = 120π/180 = 2π/3 radians.","analogyTitle":"La ficelle autour du cercle","emoji":"⭕","minutes":10,"track":"general-math6","content_version":2}'::jsonb
from public.chapters where slug='5-trigonometrie'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'5-sinus-cercle','Le sinus sur le cercle','Sur le cercle trigonométrique de rayon 1, le point d’angle θ a pour coordonnées (cos θ ; sin θ). Le sinus est donc son ordonnée.
Il est positif dans la moitié supérieure du cercle et négatif dans la moitié inférieure. Ajouter 2π ne change pas sa valeur.','Le sinus indique la hauteur relative d’une nacelle par rapport au centre. Un tour supplémentaire la ramène à la même hauteur.','Lire l’abscisse, qui correspond au cosinus, au lieu de l’ordonnée.','unit_circle',4,true,'{"description":"Lire les signes et les angles repères.","method":["Repère l’angle sur le cercle.","Lis l’ordonnée du point.","Vérifie le signe avec la moitié du cercle."],"example":"sin(π/2) = 1 et sin(3π/2) = −1.","analogyTitle":"La grande roue","emoji":"🎡","minutes":10,"track":"general-math6","content_version":2}'::jsonb
from public.chapters where slug='5-trigonometrie'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'5-produit-scalaire','Le produit scalaire','Dans un repère orthonormé du plan, u·v = xᵤxᵥ + yᵤyᵥ. On multiplie les coordonnées correspondantes puis on additionne.
Deux vecteurs non nuls sont perpendiculaires si et seulement si leur produit scalaire vaut zéro.','Le produit scalaire mesure comment deux directions coopèrent. Des directions perpendiculaires n’ont aucune composante commune dans ce sens.','Le produit scalaire est un nombre, pas un vecteur de coordonnées multipliées.','dot_product',5,true,'{"description":"Comparer les directions de deux vecteurs.","method":["Multiplie les premières coordonnées.","Multiplie les secondes coordonnées.","Additionne en conservant les signes."],"example":"(2 ; 3) · (4 ; −1) = 2 × 4 + 3 × (−1) = 5.","analogyTitle":"Tirer dans la même direction","emoji":"🧭","minutes":12,"track":"general-math6","content_version":2}'::jsonb
from public.chapters where slug='5-geometrie'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'5-limite-amovible','Une limite après simplification','Une limite décrit les valeurs approchées par une fonction quand x s’approche d’un nombre. Une forme 0/0 n’est pas un résultat : elle invite à transformer l’expression.
Pour x ≠ a, (x² − a²)/(x − a) = x + a. On peut donc trouver la limite en a à partir de cette expression simplifiée, sans affirmer que la fraction initiale est définie en a.','Une route peut avoir un trou en un point tout en indiquant clairement vers quelle hauteur on s’approche. La limite décrit l’approche, pas nécessairement une valeur au point.','Répondre 0 dès que le numérateur tend vers zéro, sans regarder le dénominateur.','removable_limit',6,true,'{"description":"Approcher un point où la formule bloque.","method":["Repère la forme indéterminée.","Factorise le numérateur puis simplifie pour x ≠ a.","Calcule la limite de l’expression obtenue."],"example":"lim quand x → 3 de (x² − 9)/(x − 3) = lim(x + 3) = 6.","analogyTitle":"Le trou dans la route","emoji":"🛤️","minutes":12,"track":"general-math6","content_version":2}'::jsonb
from public.chapters where slug='5-analyse'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'5-limite-infini','Les limites à l’infini','Pour un quotient de polynômes de même degré, la limite en +∞ est le quotient de leurs coefficients dominants.
On le voit en divisant numérateur et dénominateur par la plus grande puissance de x : les termes contenant 1/x tendent vers zéro.','À très grande échelle, les petits détails deviennent négligeables. Les termes du plus haut degré donnent le comportement principal.','Utiliser les constantes au lieu des coefficients du plus haut degré.','rational_limit',7,true,'{"description":"Repérer les termes dominants.","method":["Compare les degrés des deux polynômes.","S’ils sont égaux, repère les coefficients dominants.","Prends leur quotient."],"example":"lim quand x → +∞ de (3x² + 1)/(2x² + 5) = 3/2.","analogyTitle":"Le zoom arrière","emoji":"🔭","minutes":12,"track":"general-math6","content_version":2}'::jsonb
from public.chapters where slug='5-analyse'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'5-derivees','Dériver une puissance','Pour f(x) = axⁿ, on a f′(x) = an xⁿ⁻¹. La dérivée d’une constante vaut zéro.
La dérivée en un point donne la pente de la tangente à la courbe en ce point. Elle ne donne pas la hauteur de la courbe.','La distance parcourue décrit où tu en es ; sa dérivée décrit la vitesse à cet instant. Une position et une vitesse ne répondent pas à la même question.','Oublier de diminuer l’exposant, ou calculer f(x) à la place de f′(x).','derivative',8,true,'{"description":"Mesurer une variation instantanée.","method":["Multiplie le coefficient par l’exposant.","Diminue l’exposant de 1.","Remplace x par la valeur demandée si nécessaire."],"example":"Si f(x) = 3x², f′(x) = 6x ; donc f′(4) = 24.","analogyTitle":"Le compteur de vitesse","emoji":"🚲","minutes":12,"track":"general-math6","content_version":2}'::jsonb
from public.chapters where slug='5-analyse'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'5-tangente','L’équation d’une tangente','La tangente en x = a a pour équation y = f(a) + f′(a)(x − a). Elle passe par (a ; f(a)) et possède la pente f′(a).
Développer cette expression permet d’obtenir y = mx + p.','Tout près du point, une règle orientée comme la courbe donne une bonne approximation de son trajet. Sa pente et son point de passage sont tous deux nécessaires.','Écrire seulement y = f′(a)x : la tangente ne passe pas forcément par l’origine.','tangent',9,true,'{"description":"Une droite qui suit la courbe localement.","method":["Calcule la valeur f(a).","Calcule la pente f′(a).","Écris la droite passant par ce point avec cette pente."],"example":"Pour f(x) = x² en a = 3 : y = 9 + 6(x − 3) = 6x − 9.","analogyTitle":"La règle posée sur la courbe","emoji":"📏","minutes":12,"track":"general-math6","content_version":2}'::jsonb
from public.chapters where slug='5-analyse'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'6-exponentielle','Les modèles exponentiels','Un modèle exponentiel a la forme f(t) = A × qᵗ, avec q > 0. À chaque unité de temps, on multiplie par q.
Pour q > 1, le modèle croît ; pour 0 < q < 1, il décroît. Le coefficient A est la valeur initiale f(0).','Chaque période, la variation porte sur la nouvelle quantité, pas seulement sur celle du départ. Les effets successifs se multiplient.','Multiplier le facteur par le temps au lieu de l’élever à une puissance.','exponential',1,true,'{"description":"Accumuler des variations multiplicatives.","method":["Identifie la quantité initiale.","Repère le facteur appliqué à chaque période.","Élève le facteur au nombre de périodes puis multiplie par la quantité initiale."],"example":"Avec A = 5 et q = 3, après 2 périodes : f(2) = 5 × 3² = 45.","analogyTitle":"Les intérêts composés","emoji":"🌱","minutes":12,"track":"general-math6","content_version":2}'::jsonb
from public.chapters where slug='6-fonctions'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'6-logarithmes','Les logarithmes','Pour a > 0 et a ≠ 1, logₐ(b) est l’exposant x tel que aˣ = b, avec b > 0. Le logarithme renverse donc l’opération exponentielle.
logₐ(uv) = logₐ(u) + logₐ(v) pour u et v positifs. Cette règle ne vaut pas pour une somme u + v.','Si tu pars de 1 et doubles jusqu’à 32, tu as doublé cinq fois. Le logarithme compte le nombre d’étapes multiplicatives.','Diviser b par a ne retrouve pas l’exposant ; le logarithme d’un réel non positif n’est pas défini dans ℝ.','logarithm',2,true,'{"description":"Retrouver un exposant.","method":["Réécris la question sous la forme aˣ = b.","Cherche la puissance correspondante.","Vérifie en recalculant aˣ."],"example":"log₂(32) = 5 car 2⁵ = 32.","analogyTitle":"Combien de doubles ?","emoji":"🔢","minutes":12,"track":"general-math6","content_version":2}'::jsonb
from public.chapters where slug='6-fonctions'
on conflict (slug) do update set chapter_id=excluded.chapter_id,title=excluded.title,theory=excluded.theory,analogy=excluded.analogy,common_mistake=excluded.common_mistake,exercise_kind=excluded.exercise_kind,position=excluded.position,published=excluded.published,metadata=excluded.metadata;

insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'6-integrales','Calculer une intégrale','Si F est une primitive de f sur [a ; b], alors ∫ de a à b de f(x) dx = F(b) − F(a). Une primitive de kx est kx²/2.
L’intégrale compte des aires signées. Si la fonction est positive sur l’intervalle, elle coïncide avec l’aire sous la courbe.','Le débit donne la quantité d’eau par seconde. Son intégrale sur une durée donne la quantité totale ajoutée pendant cette durée.','Additionner les valeurs aux bornes ou oublier de retrancher F(a).','integral',3,true,'{"description":"Passer d’une variation à une accumulation.","method":["Trouve une primitive.","Évalue-la à la borne supérieure puis à la borne inférieure.","Soustrais F(b) − F(a)."],"example":"∫ de 1 à 3 de 2x dx = [x²] de 1 à 3 = 9 − 1 = 8.","analogyTitle":"Le débit du robinet","emoji":"🚰","minutes":14,"track":"general-math6","content_version":2}'::jsonb
