insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'6-probabilite-conditionnelle','Les probabilités conditionnelles','Si P(B) > 0, P(A sachant B) = P(A ∩ B) / P(B). On restreint les possibilités aux cas où B est réalisé.
Avec des effectifs, on divise le nombre de cas dans A et B par le nombre de cas dans B.','Un filtre réduit la liste des possibilités. Une fois le filtre appliqué, les proportions se calculent dans cette nouvelle liste.','Confondre P(A sachant B) et P(B sachant A), ou garder l’ancien dénominateur.','conditional_probability',4,true,'{"description":"Changer l’univers quand on reçoit une information.","method":["Identifie la condition B.","Compte les cas de A à l’intérieur de B.","Divise par l’effectif de B, pas par l’effectif total."],"example":"Parmi 12 élèves qui font du sport, 5 jouent au tennis : P(tennis sachant sport) = 5/12.","analogyTitle":"Le filtre de recherche","emoji":"🔎","minutes":12,"track":"general-math6","content_version":2}'::jsonb
