insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'6-combinaisons','Dénombrer des choix','Le nombre de façons de choisir k objets parmi n, sans répétition et sans ordre, est C(n,k) = n! / (k!(n − k)!).
Pour choisir une paire, cela donne n(n − 1)/2. On divise par 2 car chaque paire a été comptée dans les deux ordres.','Alice–Benoît et Benoît–Alice forment la même équipe. Les compter séparément doublerait le nombre réel de duos.','Utiliser n(n − 1) pour une paire sans ordre compte chaque paire deux fois.','combinations',5,true,'{"description":"Choisir sans tenir compte de l’ordre.","method":["Vérifie que l’ordre ne compte pas.","Compte les choix successifs distincts.","Divise par le nombre d’ordres possibles."],"example":"Parmi 6 personnes, on peut choisir 6 × 5 / 2 = 15 équipes de deux.","analogyTitle":"Le duo","emoji":"🤝","minutes":12,"track":"general-math6","content_version":2}'::jsonb
