insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'6-loi-binomiale','La loi binomiale','Une loi binomiale modélise le nombre de succès dans n essais indépendants, chacun avec la même probabilité p de succès.
P(X = k) = C(n,k) pᵏ (1 − p)ⁿ⁻ᵏ. Le coefficient compte les positions possibles des k succès.','Un unique pile peut arriver au premier, au deuxième ou au troisième lancer. Il faut compter ces chemins différents.','Oublier le coefficient de combinaison, ou appliquer le modèle à des essais dépendants.','binomial',6,true,'{"description":"Compter les succès dans des essais indépendants.","method":["Vérifie indépendance et probabilité constante.","Calcule la probabilité d’un ordre précis de succès et d’échecs.","Multiplie par le nombre de positions possibles."],"example":"Avec 3 lancers d’une pièce équilibrée, P(exactement 1 pile) = 3 × (1/2)³ = 3/8.","analogyTitle":"Plusieurs chemins vers un succès","emoji":"🪙","minutes":14,"track":"general-math6","content_version":2}'::jsonb
