insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'6-loi-normale','Centrer et réduire','Pour une variable de moyenne μ et d’écart-type σ > 0, la variable centrée réduite est Z = (X − μ)/σ.
Si X suit une loi normale, Z suit une loi normale de moyenne 0 et d’écart-type 1. Un score z mesure un nombre d’écarts-types ; il ne représente pas une probabilité.','Être dix points au-dessus de la moyenne n’a pas le même sens dans un groupe très homogène ou très dispersé. L’écart-type adapte l’échelle.','Diviser par la variance σ² au lieu de l’écart-type σ.','standardization',7,true,'{"description":"Comparer un écart à la dispersion.","method":["Soustrais la moyenne à la valeur observée.","Divise par l’écart-type.","Interprète le signe et le nombre d’écarts-types."],"example":"Pour X = 75, μ = 60 et σ = 5 : z = (75 − 60)/5 = 3.","analogyTitle":"Une règle adaptée au groupe","emoji":"📊","minutes":14,"track":"general-math6","content_version":2}'::jsonb
