insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'6-optimisation','Optimiser avec la dérivée','Pour chercher un extremum, on étudie la dérivée et son signe. Une dérivée nulle fournit un candidat, pas automatiquement un maximum.
Pour f(x) = −ax² + bx avec a > 0, f′(x) = −2ax + b. La dérivée passe de positive à négative en x = b/(2a) : on y trouve un maximum.','Avant le sommet, tu montes ; après, tu descends. Une pente nulle ne suffit pas : il faut vérifier ce qui se passe de chaque côté.','Donner f(x) alors qu’on demande où le maximum est atteint, ou oublier les bornes du domaine.','optimization',8,true,'{"description":"Trouver la meilleure valeur sous une contrainte.","method":["Dérive la fonction.","Résous f′(x) = 0.","Vérifie le changement de signe et les limites du domaine."],"example":"f(x) = −2x² + 12x : f′(x) = −4x + 12, donc maximum en x = 3.","analogyTitle":"Le sommet de la colline","emoji":"🏔️","minutes":14,"track":"general-math6","content_version":2}'::jsonb
