insert into public.lessons (chapter_id,slug,title,theory,analogy,common_mistake,exercise_kind,position,published,metadata)
select id,'6-aire-entre-courbes','L’aire entre deux courbes','Si f(x) ≥ g(x) sur [a ; b], l’aire entre les courbes vaut ∫ de a à b de (f(x) − g(x)) dx.
Si les courbes se croisent, il faut découper l’intervalle et repérer laquelle est au-dessus sur chaque morceau.','Découpe mentalement la zone en fines bandes verticales. La hauteur de chaque bande est la différence entre les deux courbes.','Soustraire dans le mauvais ordre peut donner une intégrale négative alors que l’aire est positive.','area_between',9,true,'{"description":"Accumuler la différence de hauteur.","method":["Détermine la courbe du dessus sur l’intervalle.","Soustrais la fonction du dessous.","Intègre la différence entre les bornes."],"example":"Entre y = 3x et y = x sur [0 ; 2] : aire = ∫ de 0 à 2 de 2x dx = 4.","analogyTitle":"Les bandes de tissu","emoji":"🧵","minutes":14,"track":"general-math6","content_version":2}'::jsonb
